/*--------------------------------------------------------------
 * _ctl_strip_prep_needed — does strip r0 have to rebuild its
 * ROUTING control state this block?
 *
 * In:  r0 = strip index, 0..31
 * Out: returns with AZ SET (so the caller's `if eq jump` is
 *      taken) when the prep can be SKIPPED. When it cannot, the
 *      node's epoch has already been updated to the value read
 *      here and AZ is clear.
 * Clobbers: r1, r2, r3, r4, i4, m4, l4.
 *
 * THE EPOCH IS STORED HERE, BEFORE the caller preps, and that is
 * deliberate in the other direction from the obvious: the value
 * stored is the one READ at this instant, so an SPI write that
 * lands while the prep runs leaves _ctl_epoch AHEAD of what was
 * stored and is picked up on the next block. Storing the epoch
 * read AFTER the prep would swallow it.
 *-------------------------------------------------------------*/
.global _ctl_strip_prep_needed;
_ctl_strip_prep_needed:
    l4 = 0;
    m4 = r0;
    i4 = _ctl_epoch;
    modify(i4, m4);
    r4 = dm(i4, 0);                 /* this strip's epoch    */
    i4 = _rtg_ep;
    modify(i4, m4);
    r1 = dm(i4, 0);
    r1 = r1 xor r4;                 /* 0 iff unchanged       */
    i4 = _rtg_busy;
    modify(i4, m4);
    r2 = dm(i4, 0);
    r1 = r1 or r2;                  /* own send ramps        */
    i4 = _fdr_busy_ptrs;
    modify(i4, m4);
    r3 = dm(i4, 0);
    i4 = r3;
    r2 = dm(i4, 0);
    r1 = r1 or r2;                  /* the fader's pan ramp  */
    if eq rts;                      /* nothing to do         */
    i4 = _rtg_ep;
    modify(i4, m4);
    dm(i4, 0) = r4;
    r1 = pass r1;                   /* leave AZ clear        */
    rts;
_ctl_strip_prep_needed.end:
